(4521499, 652051, 66384, '<td valign="top">Nice image. I like the crossing lines of color. However, I think you might not have read the details of this challenge.</td>', 'Nice image. I like the crossing lines of color. However, I think you might not have read the details of this challenge.', '2008-02-27 11:13:31.000000', NULL, 1),
(4521503, 651557, 66384, '<td valign="top">There does not seem to be any primary subject against the same color background. It is a pretty sky though.</td>', 'There does not seem to be any primary subject against the same color background. It is a pretty sky though.', '2008-02-27 11:17:27.000000', NULL, 1),
(4521520, 652066, 66384, '<td valign="top">This is so yellow (except for the eyes) that it looks like a yellow layer was applied over the whole image. Perhaps it is just the lack of contrast that gives that impression. I would like this better with stronger contrast.</td>', 'This is so yellow (except for the eyes) that it looks like a yellow layer was applied over the whole image. Perhaps it is just the lack of contrast that gives that impression. I would like this better with stronger contrast.', '2008-02-27 11:22:13.000000', NULL, 1),
(4521525, 651941, 66384, '<td valign="top">The depth of field is a bit too shallow for me. Almost nothing is in focus. I like the colors and the lines of the image though.</td>', 'The depth of field is a bit too shallow for me. Almost nothing is in focus. I like the colors and the lines of the image though.', '2008-02-27 11:23:58.000000', NULL, 1),
(4521534, 650516, 66384, '<td valign="top">This is a WOW for me. Beautiful clarity and very nice DOF. Fascinating subject and lovely colors.</td>', 'This is a WOW for me. Beautiful clarity and very nice DOF. Fascinating subject and lovely colors.', '2008-02-27 11:25:43.000000', NULL, 1),
(4521549, 650591, 66384, '<td valign="top">Really nice. Would look great in very large format on a huge white wall. The sort of image I would never tire of seeing. I wonder if this really meets the challenge since the ice seems to be without color, but hey, I''m not that particular. 9</td>', 'Really nice. Would look great in very large format on a huge white wall. The sort of image I would never tire of seeing. I wonder if this really meets the challenge since the ice seems to be without color, but hey, I''m not that particular. 9', '2008-02-27 11:28:54.000000', NULL, 1),
