(4521698, 650670, 66384, '<td valign="top">The colors are good, but the crop bothers me a bit -- the extra blank space at the top while the third seed pod is chopped off.</td>', 'The colors are good, but the crop bothers me a bit -- the extra blank space at the top while the third seed pod is chopped off.', '2008-02-27 11:53:49.000000', NULL, 1),
