(4521711, 649644, 66384, '<td valign="top">Yummy! Exquisite color, focus, and DOF.</td>', 'Yummy! Exquisite color, focus, and DOF.', '2008-02-27 11:57:09.000000', NULL, 1),
(4521720, 652017, 66384, '<td valign="top">I did think of Shez when I saw this -- even before I saw the title. Very pretty.</td>', 'I did think of Shez when I saw this -- even before I saw the title. Very pretty.', '2008-02-27 11:58:52.000000', NULL, 1),
(4521734, 650757, 66384, '<td valign="top">Very, very pretty. Beautiful focus and DOF. There seems to be a lit too much difference in color between the subject and the green background for this challenge.</td>', 'Very, very pretty. Beautiful focus and DOF. There seems to be a lit too much difference in color between the subject and the green background for this challenge.', '2008-02-27 12:01:08.000000', NULL, 1),
(4521750, 651437, 66384, '<td valign="top">Fun. Takes me back to my snowman building days -- trying to get the snowballs started in the rolling process. Certainly nails the challenge.</td>', 'Fun. Takes me back to my snowman building days -- trying to get the snowballs started in the rolling process. Certainly nails the challenge.', '2008-02-27 12:03:59.000000', NULL, 1),
(4521772, 650373, 66384, '<td valign="top">I think you have a winner here. Beautiful form.</td>', 'I think you have a winner here. Beautiful form.', '2008-02-27 12:07:47.000000', NULL, 1),
(4521798, 649510, 66384, '<td valign="top">Focus and noise are a problem for me here.</td>', 'Focus and noise are a problem for me here.', '2008-02-27 12:11:33.000000', NULL, 1),
(4521977, 652045, 61679, '<td valign="top">I love the total subject matter and the post processing; however, the pot appears to be the strongest subject in the photo to me and it doesn''t match the background color very well.  I also find the extra space on the right side of the image makes the composition look a bit unbalanced.  I realize some of it is due to the foliage hanging over the side of the chair but a bit more space on the left would have provided better balance.</td>', 'I love the total subject matter and the post processing; however, the pot appears to be the strongest subject in the photo to me and it doesn''t match the background color very well.  I also find the extra space on the right side of the image makes the composition look a bit unbalanced.  I realize some of it is due to the foliage hanging over the side of the chair but a bit more space on the left would have provided better balance.', '2008-02-27 12:41:58.000000', NULL, 1),
(4522029, 652064, 61679, '<td valign="top">If you would have cropped off the left half of the image and a little at the top (get rid of the non-green area), I could have given this a solid 7 score.  As is, the composition is weakened by the many distractions like the bright spots and the water drops.  Cropping would also have given you a lot more room to manipulate the contrast in post processing.</td>', 'If you would have cropped off the left half of the image and a little at the top (get rid of the non-green area), I could have given this a solid 7 score.  As is, the composition is weakened by the many distractions like the bright spots and the water drops.  Cropping would also have given you a lot more room to manipulate the contrast in post processing.', '2008-02-27 12:52:49.000000', NULL, 1),
(4522054, 650819, 55212, '<td valign="top">Point &amp; shoot camera? It''s very grainy.</td>', 'Point & shoot camera? It''s very grainy.', '2008-02-27 12:58:30.000000', NULL, 1),
(4522145, 649752, 90280, '<td valign="top">Love the enveloping flame. Added a great deal to this photo.</td>', 'Love the enveloping flame. Added a great deal to this photo.', '2008-02-27 13:21:34.000000', NULL, 1),
(4522163, 651619, 83375, '<td valign="top">For me this isn''t what the challenge was about..I think you need to either concentrate on ONE color or have the background match up very well, and this shot does neither.</td>', 'For me this isn''t what the challenge was about..I think you need to either concentrate on ONE color or have the background match up very well, and this shot does neither.', '2008-02-27 13:27:55.000000', NULL, 1),
(4522171, 651924, 83375, '<td valign="top">The richness of the color really makes this one of my favorites so far.  Great details.</td>', 'The richness of the color really makes this one of my favorites so far.  Great details.', '2008-02-27 13:32:05.000000', NULL, 1),
