(4522330, 651167, 48268, '<td valign="top">Beautiful!</td>', 'Beautiful!', '2008-02-27 14:25:55.000000', NULL, 1),
(4522332, 652019, 89219, '<td valign="top">Let down by lighting. Most the picture lacks detail and sharpness and the lemon right at the front is in lost in the shadows.</td>', 'Let down by lighting. Most the picture lacks detail and sharpness and the lemon right at the front is in lost in the shadows.', '2008-02-27 14:26:28.000000', NULL, 1),
(4522348, 652004, 89219, '<td valign="top">Centre of the flower isn''t well enough lit and kinda feels a bit flat.  Not sure the composition is as good as it could be.  <br/> <br/>Saying that I do still like the simplicity of the flower and colours.  I find this one of the more interesting flower shots for its lack of fuss. I''d take that further and remove the background flowers and put some space to the left.</td>', 'Centre of the flower isn''t well enough lit and kinda feels a bit flat.  Not sure the composition is as good as it could be.   Saying that I do still like the simplicity of the flower and colours.  I find this one of the more interesting flower shots for its lack of fuss. I''d take that further and remove the background flowers and put some space to the left.', '2008-02-27 14:32:40.000000', NULL, 1),
(4522350, 652045, 48268, '<td valign="top">I love it!</td>', 'I love it!', '2008-02-27 14:34:52.000000', NULL, 1),
