(4530743, 652054, 34462, '<td valign="top">Nice capture and very clear.</td>', 'Nice capture and very clear.', '2008-03-01 15:25:44.000000', NULL, 1),
(4530744, 650059, 34462, '<td valign="top">Love those fajitas and this picture is good too.</td>', 'Love those fajitas and this picture is good too.', '2008-03-01 15:25:48.000000', NULL, 1),
(4530745, 649985, 34462, '<td valign="top">Ummm. I am hungry. Nice picture</td>', 'Ummm. I am hungry. Nice picture', '2008-03-01 15:25:50.000000', NULL, 1),
(4530747, 650542, 34462, '<td valign="top">Very intense eyes. I thought about doing something like this but entered the other challenge instead.</td>', 'Very intense eyes. I thought about doing something like this but entered the other challenge instead.', '2008-03-01 15:25:54.000000', NULL, 1),
(4530748, 651795, 34462, '<td valign="top">This is really cool. I like the way he blends in with the BG.</td>', 'This is really cool. I like the way he blends in with the BG.', '2008-03-01 15:25:57.000000', NULL, 1),
(4530749, 650305, 34462, '<td valign="top">Don''t tell him but he looks like a shrimp.</td>', 'Don''t tell him but he looks like a shrimp.', '2008-03-01 15:26:01.000000', NULL, 1),
(4530751, 650069, 34462, '<td valign="top">Nice high-key shot. love the eyes</td>', 'Nice high-key shot. love the eyes', '2008-03-01 15:26:04.000000', NULL, 1),
(4530753, 651959, 34462, '<td valign="top">nicely done</td>', 'nicely done', '2008-03-01 15:26:08.000000', NULL, 1),
(4530754, 650670, 34462, '<td valign="top">Those are interesting. like to focus and the BG.</td>', 'Those are interesting. like to focus and the BG.', '2008-03-01 15:26:12.000000', NULL, 1),
(4530755, 651607, 34462, '<td valign="top">Nice white on white</td>', 'Nice white on white', '2008-03-01 15:26:19.000000', NULL, 1),
(4530764, 651171, 53509, '<td valign="top">Such sharpness and a great expression. Love it!</td>', 'Such sharpness and a great expression. Love it!', '2008-03-01 15:33:58.000000', NULL, 1),
(4530767, 651188, 53509, '<td valign="top">Sharp and colourful. It doesn''t seem to lead my eye anywhere in particular.</td>', 'Sharp and colourful. It doesn''t seem to lead my eye anywhere in particular.', '2008-03-01 15:34:29.000000', NULL, 1),
(4530769, 649170, 53509, '<td valign="top">I''m afraid I''m a bit lost on where you were going with this one. The background is too cluttered. Doesn''t meet the challenge.</td>', 'I''m afraid I''m a bit lost on where you were going with this one. The background is too cluttered. Doesn''t meet the challenge.', '2008-03-01 15:35:14.000000', NULL, 1),
(4530771, 651166, 53509, '<td valign="top">I like the way the light plays on the fall. The photo doesn''t seem to meet the topic strongly, in my opinion.</td>', 'I like the way the light plays on the fall. The photo doesn''t seem to meet the topic strongly, in my opinion.', '2008-03-01 15:35:42.000000', NULL, 1),
(4530773, 650060, 53509, '<td valign="top">This does not meet the challenge topic. I do like the choice of colours though.</td>', 'This does not meet the challenge topic. I do like the choice of colours though.', '2008-03-01 15:36:41.000000', NULL, 1),
(4530775, 651957, 53509, '<td valign="top">Sharp with an interesting subject.</td>', 'Sharp with an interesting subject.', '2008-03-01 15:37:03.000000', NULL, 1),
(4530778, 650420, 53509, '<td valign="top">I like the texture of the cloth. Parts of the rose seem a bit unfocused and it distracts me.</td>', 'I like the texture of the cloth. Parts of the rose seem a bit unfocused and it distracts me.', '2008-03-01 15:37:47.000000', NULL, 1),
(4530780, 651535, 53509, '<td valign="top">Interesting use of perspective. The background colour seems a bit strong... I wish it were a bit lighter.</td>', 'Interesting use of perspective. The background colour seems a bit strong... I wish it were a bit lighter.', '2008-03-01 15:38:25.000000', NULL, 1),
(4530781, 650837, 53509, '<td valign="top">Good matching of colour. The lighting seems a bit flat to me.</td>', 'Good matching of colour. The lighting seems a bit flat to me.', '2008-03-01 15:38:59.000000', NULL, 1),
(4530783, 650542, 53509, '<td valign="top">An interesting take on the challenge. The eyes do stand out well. The face doesn''t seem sharp enough to quite work.</td>', 'An interesting take on the challenge. The eyes do stand out well. The face doesn''t seem sharp enough to quite work.', '2008-03-01 15:39:29.000000', NULL, 1),
(4530786, 651517, 53509, '<td valign="top">I love the colours of green here. There''s just a little too much happening in the background. The foreground needs to be sharper.</td>', 'I love the colours of green here. There''s just a little too much happening in the background. The foreground needs to be sharper.', '2008-03-01 15:40:10.000000', NULL, 1),
(4530789, 651424, 53509, '<td valign="top">An interesting creature! He must be sharper in the eye area - it keeps distracting me. It''s also too bad that his nose is cut off. The background is also too cluttered - I don''t know what is the white and red stuff in the top half, but if you subtracted it, you would improve the composition considerably!</td>', 'An interesting creature! He must be sharper in the eye area - it keeps distracting me. It''s also too bad that his nose is cut off. The background is also too cluttered - I don''t know what is the white and red stuff in the top half, but if you subtracted it, you would improve the composition considerably!', '2008-03-01 15:41:34.000000', NULL, 1),
(4530791, 650516, 53509, '<td valign="top">Great use of sharpness and light to define and interesting subject! Terrific!</td>', 'Great use of sharpness and light to define and interesting subject! Terrific!', '2008-03-01 15:42:00.000000', NULL, 1),
(4530793, 651952, 53509, '<td valign="top">The reds are well-matched here. I wish there was a bit more light on the berries themselves - I think the photo would "pop" with some more highlights on the berries.</td>', 'The reds are well-matched here. I wish there was a bit more light on the berries themselves - I think the photo would "pop" with some more highlights on the berries.', '2008-03-01 15:42:30.000000', NULL, 1),
(4530795, 651921, 53509, '<td valign="top">Interesting texture in the flowers. There''s a lot happening here - I''m not sure if the lines in the background work well in the composition.</td>', 'Interesting texture in the flowers. There''s a lot happening here - I''m not sure if the lines in the background work well in the composition.', '2008-03-01 15:43:04.000000', NULL, 1),
(4530797, 651089, 53509, '<td valign="top">Good expression! Perhaps a higher angle would help cut off the background.</td>', 'Good expression! Perhaps a higher angle would help cut off the background.', '2008-03-01 15:43:27.000000', NULL, 1),
(4530798, 652074, 53509, '<td valign="top">I love the definition of the eggs here!</td>', 'I love the definition of the eggs here!', '2008-03-01 15:43:37.000000', NULL, 1),
(4530803, 650372, 53509, '<td valign="top">Wonderful "sparkliness". The petal sticking up bothers me a bit.</td>', 'Wonderful "sparkliness". The petal sticking up bothers me a bit.', '2008-03-01 15:44:20.000000', NULL, 1),
(4530804, 650150, 53509, '<td valign="top">Creative take on the challenge. I like the use of light.</td>', 'Creative take on the challenge. I like the use of light.', '2008-03-01 15:44:47.000000', NULL, 1),
(4530807, 650599, 53509, '<td valign="top">This doesn''t seem to meet the challenge strongly.</td>', 'This doesn''t seem to meet the challenge strongly.', '2008-03-01 15:45:11.000000', NULL, 1),
(4530808, 651537, 53509, '<td valign="top">I like this idea - well-executed.</td>', 'I like this idea - well-executed.', '2008-03-01 15:45:26.000000', NULL, 1),
(4530811, 651926, 53509, '<td valign="top">The peas are nice and sharp. There''s a bit too many colours here for this challenge - too many shades of green. Also, I would have picked out the orange peas.</td>', 'The peas are nice and sharp. There''s a bit too many colours here for this challenge - too many shades of green. Also, I would have picked out the orange peas.', '2008-03-01 15:46:04.000000', NULL, 1),
(4530812, 652061, 53509, '<td valign="top">This doesn''t meet the challenge topic.</td>', 'This doesn''t meet the challenge topic.', '2008-03-01 15:46:18.000000', NULL, 1),
(4530815, 649093, 53509, '<td valign="top">I think the composition could be improved with a little less foreground.</td>', 'I think the composition could be improved with a little less foreground.', '2008-03-01 15:46:50.000000', NULL, 1),
(4530817, 652076, 53509, '<td valign="top">Interesting capture! For me, too many colours to meet the challenge strongly.</td>', 'Interesting capture! For me, too many colours to meet the challenge strongly.', '2008-03-01 15:47:15.000000', NULL, 1),
(4530818, 651787, 53509, '<td valign="top">Beautiful lighting!</td>', 'Beautiful lighting!', '2008-03-01 15:47:28.000000', NULL, 1),
(4530821, 651944, 53509, '<td valign="top">I like how the flower grows from the frame.</td>', 'I like how the flower grows from the frame.', '2008-03-01 15:48:06.000000', NULL, 1),
(4530823, 650819, 53509, '<td valign="top">This photo does not meet the challenge.</td>', 'This photo does not meet the challenge.', '2008-03-01 15:48:58.000000', NULL, 1),
(4530824, 651091, 53509, '<td valign="top">The shadow is too strong and detracts from the tomato. Also, I would be careful to pick a tomato with a better looking green top.</td>', 'The shadow is too strong and detracts from the tomato. Also, I would be careful to pick a tomato with a better looking green top.', '2008-03-01 15:49:34.000000', NULL, 1),
(4530825, 651381, 53509, '<td valign="top">Appealing and interesting perspective.</td>', 'Appealing and interesting perspective.', '2008-03-01 15:49:48.000000', NULL, 1),
(4530826, 651985, 53509, '<td valign="top">I like the angle of the flower. To me, the petal draws my attention more than the bud though...</td>', 'I like the angle of the flower. To me, the petal draws my attention more than the bud though...', '2008-03-01 15:50:16.000000', NULL, 1),
(4530829, 651797, 53509, '<td valign="top">Just wish it was a bit sharper in the petals. Also, the light is distractingly uneven on the petals.</td>', 'Just wish it was a bit sharper in the petals. Also, the light is distractingly uneven on the petals.', '2008-03-01 15:50:54.000000', NULL, 1),
(4530830, 651066, 53509, '<td valign="top">Just gorgeous!</td>', 'Just gorgeous!', '2008-03-01 15:51:07.000000', NULL, 1),
(4530832, 650700, 53509, '<td valign="top">What fantastic lighting! Wonderful.</td>', 'What fantastic lighting! Wonderful.', '2008-03-01 15:51:20.000000', NULL, 1),
(4530834, 651658, 53509, '<td valign="top">Creative, with good use of a blurred background.</td>', 'Creative, with good use of a blurred background.', '2008-03-01 15:51:39.000000', NULL, 1),
(4530836, 651610, 53509, '<td valign="top">Beautiful leaf. The dark spots in the background take my eye away from the leaf.</td>', 'Beautiful leaf. The dark spots in the background take my eye away from the leaf.', '2008-03-01 15:52:25.000000', NULL, 1),
(4530839, 651959, 53509, '<td valign="top">I love the definition in the petal</td>', 'I love the definition in the petal', '2008-03-01 15:53:08.000000', NULL, 1),
(4530843, 652037, 53509, '<td valign="top">I like the way the apple is lit!</td>', 'I like the way the apple is lit!', '2008-03-01 15:54:25.000000', NULL, 1),
(4530844, 651715, 53509, '<td valign="top">The shadow on the bike is distracting.</td>', 'The shadow on the bike is distracting.', '2008-03-01 15:54:41.000000', NULL, 1),
(4530846, 651082, 53509, '<td valign="top">I like the spotlight on the tomatoes.</td>', 'I like the spotlight on the tomatoes.', '2008-03-01 15:54:52.000000', NULL, 1),
(4530850, 652017, 53509, '<td valign="top">This doesn''t meet the challenge topic.</td>', 'This doesn''t meet the challenge topic.', '2008-03-01 15:55:57.000000', NULL, 1),
(4530926, 651097, 55005, '<td valign="top">I don''t know what you did to get him(her?) to model like that.  Love all the details, especially the detials on the neck.  Very well done.</td>', 'I don''t know what you did to get him(her?) to model like that.  Love all the details, especially the detials on the neck.  Very well done.', '2008-03-01 16:31:47.000000', NULL, 1),
(4531044, 651097, 83350, '<td valign="top">As a former Marine, I am not sure if I am upset or giddy - LOL - He/she is almost to CUTE to wear the uniform!! Semper Fi anyway!! Oh, Labs have such beautiful eyes, it would have been nice to light them a bit more. 10 non-the less!!</td>', 'As a former Marine, I am not sure if I am upset or giddy - LOL - He/she is almost to CUTE to wear the uniform!! Semper Fi anyway!! Oh, Labs have such beautiful eyes, it would have been nice to light them a bit more. 10 non-the less!!', '2008-03-01 17:39:11.000000', NULL, 1),
(4531059, 651437, 83350, '<td valign="top">No matter how well it does in the overall contest, gotta get a 10 for a GREAT imagination!!</td>', 'No matter how well it does in the overall contest, gotta get a 10 for a GREAT imagination!!', '2008-03-01 17:46:05.000000', NULL, 1),
(4531072, 650545, 90380, '<td valign="top">Very cool concept, it''s just too bad about the blurriness.</td>', 'Very cool concept, it''s just too bad about the blurriness.', '2008-03-01 17:56:07.000000', NULL, 1),
(4531076, 651389, 90380, '<td valign="top">What a beautiful little scary guy! Very nice job.</td>', 'What a beautiful little scary guy! Very nice job.', '2008-03-01 17:57:37.000000', NULL, 1),
(4531084, 650371, 3087, '<td valign="top">Beautiful! I really like the diagonal lines the petals bring to the composition and the details in the petal tips too. The inclusion of that dark corner echoes the black spots and body parts of the ladybird just as the petals echo the red of the wing casing. Really nice image.</td>', 'Beautiful! I really like the diagonal lines the petals bring to the composition and the details in the petal tips too. The inclusion of that dark corner echoes the black spots and body parts of the ladybird just as the petals echo the red of the wing casing. Really nice image.', '2008-03-01 18:01:43.000000', NULL, 1),
(4531091, 651131, 3087, '<td valign="top">Goodness, that''s vivid! I like how parts of the critter almost melt into the background. Love the shallow DOF choice too.</td>', 'Goodness, that''s vivid! I like how parts of the critter almost melt into the background. Love the shallow DOF choice too.', '2008-03-01 18:02:59.000000', NULL, 1),
(4531096, 651830, 3087, '<td valign="top">I really like this a lot particularly the contrast between the smooth texture of the surface and the wooden, hand-coloured top. My only minor negative is that the pale stripe of the surface falls at the top right of the image because it kind of gets lost there and makes the background seem less complete, less rectangular. I think it would be worth having one of the stronger colours at the edges to make sure the edges are defined.</td>', 'I really like this a lot particularly the contrast between the smooth texture of the surface and the wooden, hand-coloured top. My only minor negative is that the pale stripe of the surface falls at the top right of the image because it kind of gets lost there and makes the background seem less complete, less rectangular. I think it would be worth having one of the stronger colours at the edges to make sure the edges are defined.', '2008-03-01 18:04:34.000000', NULL, 1),
(4531100, 650444, 811, '<td valign="top">There is some halo-ing around the top.  Otherwise, I like the composition and lighting.</td>', 'There is some halo-ing around the top.  Otherwise, I like the composition and lighting.', '2008-03-01 18:05:56.000000', NULL, 1),
(4531102, 652047, 3087, '<td valign="top">I really, really like the tarnished vertical backdrop. The variety of metals each with a subtly different colour, sheen and wear works really well. I like the composition too - giving the entire top half of the image over to that backdrop works well.</td>', 'I really, really like the tarnished vertical backdrop. The variety of metals each with a subtly different colour, sheen and wear works really well. I like the composition too - giving the entire top half of the image over to that backdrop works well.', '2008-03-01 18:06:41.000000', NULL, 1),
(4531103, 651971, 3087, '<td valign="top">Gorgeous colours, textures and lines and wonderful warm red light too.</td>', 'Gorgeous colours, textures and lines and wonderful warm red light too.', '2008-03-01 18:07:13.000000', NULL, 1),
(4531105, 651959, 3087, '<td valign="top">Lovely detail in the petals and nice DOF.</td>', 'Lovely detail in the petals and nice DOF.', '2008-03-01 18:07:31.000000', NULL, 1),
(4531108, 651733, 3087, '<td valign="top">Lovely vivid greens and I like your composition and your choice of DOF to blur out some of the foreground and all of the background leaves.</td>', 'Lovely vivid greens and I like your composition and your choice of DOF to blur out some of the foreground and all of the background leaves.', '2008-03-01 18:08:00.000000', NULL, 1),
(4531110, 651595, 3087, '<td valign="top">Wow! That''s gorgeous! And I love the difference in scale between that tiny caterpillar and the yellow petals. Lovely composition too - good choice not to go for the standard ROT positioning of the caterpillar. This works!</td>', 'Wow! That''s gorgeous! And I love the difference in scale between that tiny caterpillar and the yellow petals. Lovely composition too - good choice not to go for the standard ROT positioning of the caterpillar. This works!', '2008-03-01 18:09:01.000000', NULL, 1),
(4531112, 651599, 3087, '<td valign="top">Fine art! Just beautiful. The quality of light (and shadow) is just masterly here as is the simple composition and the fantastic effect of the shallow DOF on bottle and glass. I LOVE THIS.</td>', 'Fine art! Just beautiful. The quality of light (and shadow) is just masterly here as is the simple composition and the fantastic effect of the shallow DOF on bottle and glass. I LOVE THIS.', '2008-03-01 18:09:57.000000', NULL, 1),
(4531115, 650305, 3087, '<td valign="top">Interesting opposing diagonals and strong lines.</td>', 'Interesting opposing diagonals and strong lines.', '2008-03-01 18:10:57.000000', NULL, 1),
(4531117, 651782, 811, '<td valign="top">This is a neat idea, I just think it could be "worked" to be more effective.  The composition is a bit flat.  The viewer looks from the left to the right to the left, and that is just kinda it.  Perhaps if the smaller glass was in front of the bigger one, and off to the side just a touch, it would set up a diagonal line to lead the eyes through the shot.  If you needed one glass to be higher, you could sit it on something (catalogs work well) since that is cropped out anyway.  <br/> <br/>Also, while you have "color on color" there is little to distinguish the subjects from the background.  It *almost* looks like you simply "washed" the entire shot with an orange color.  A bit more light may help that.  I have found that flashlights, or even my husbands worklights can give me a little extra "boost."  If they are too harsh, you can cover them with a tissue or papertowel or something to diffuse the light (be careful, they can get hot).<br/> <br/>If you already knew all this and this picture looks exactly like you want, my apologies.  :)</td>', 'This is a neat idea, I just think it could be "worked" to be more effective.  The composition is a bit flat.  The viewer looks from the left to the right to the left, and that is just kinda it.  Perhaps if the smaller glass was in front of the bigger one, and off to the side just a touch, it would set up a diagonal line to lead the eyes through the shot.  If you needed one glass to be higher, you could sit it on something (catalogs work well) since that is cropped out anyway.   Also, while you have "color on color" there is little to distinguish the subjects from the background.  It *almost* looks like you simply "washed" the entire shot with an orange color.  A bit more light may help that.  I have found that flashlights, or even my husbands worklights can give me a little extra "boost."  If they are too harsh, you can cover them with a tissue or papertowel or something to diffuse the light (be careful, they can get hot). If you already knew all this and this picture looks exactly like you want, my apologies.  :)', '2008-03-01 18:13:11.000000', NULL, 1),
(4531119, 651957, 79141, '<td valign="top">amazing image</td>', 'amazing image', '2008-03-01 18:15:50.000000', NULL, 1),
(4531123, 649752, 79141, '<td valign="top">brilliant</td>', 'brilliant', '2008-03-01 18:20:21.000000', NULL, 1),
(4531128, 649219, 79141, '<td valign="top">wow is that his real eye color?</td>', 'wow is that his real eye color?', '2008-03-01 18:21:52.000000', NULL, 1),
(4531144, 650540, 79141, '<td valign="top">wonderful so sharp</td>', 'wonderful so sharp', '2008-03-01 18:32:44.000000', NULL, 1),
(4531145, 650048, 79141, '<td valign="top">love this</td>', 'love this', '2008-03-01 18:32:52.000000', NULL, 1),
(4531147, 650371, 79141, '<td valign="top">great capture</td>', 'great capture', '2008-03-01 18:33:03.000000', NULL, 1),
(4531148, 651668, 79141, '<td valign="top">very nice  best W on W so far</td>', 'very nice  best W on W so far', '2008-03-01 18:33:10.000000', NULL, 1),
(4531159, 651670, 90380, '<td valign="top">Very nice colour match, and so far, a unique subject. I''d score it as one of my favourites if only the corn didn''t look kinda wrinkly and dry. So close!</td>', 'Very nice colour match, and so far, a unique subject. I''d score it as one of my favourites if only the corn didn''t look kinda wrinkly and dry. So close!', '2008-03-01 18:38:10.000000', NULL, 1),
(4531508, 651588, 88352, '<td valign="top">Very nice example of color on color in a natural environment!</td>', 'Very nice example of color on color in a natural environment!', '2008-03-01 21:32:16.000000', NULL, 1),
(4531532, 651729, 15407, '<td valign="top">Elf (in focus)nicely matches the ''on color''...</td>', 'Elf (in focus)nicely matches the ''on color''...', '2008-03-01 21:44:49.000000', NULL, 1),
(4531583, 651125, 83754, '<td valign="top">Interesting composition, but it seems a little dark.</td>', 'Interesting composition, but it seems a little dark.', '2008-03-01 22:20:14.000000', NULL, 1),
(4531587, 651071, 15407, '<td valign="top">The bright spots on the berries distract somewhat for me</td>', 'The bright spots on the berries distract somewhat for me', '2008-03-01 22:23:53.000000', NULL, 1),
(4531591, 650371, 83754, '<td valign="top">Very nice detail on the ladybug.</td>', 'Very nice detail on the ladybug.', '2008-03-01 22:25:31.000000', NULL, 1),
(4531608, 651434, 83754, '<td valign="top">Nice shot.  Maybe the dark edge to the left should be cropped out a bit as it is a little distracting from the very nice flowers.</td>', 'Nice shot.  Maybe the dark edge to the left should be cropped out a bit as it is a little distracting from the very nice flowers.', '2008-03-01 22:38:42.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4531919, 651084, 43565, '<td valign="top">My favorite of the painted faces so far.</td>', 'My favorite of the painted faces so far.', '2008-03-02 03:07:48.000000', NULL, 1),
(4531921, 650069, 43565, '<td valign="top">Very nice portrait.  I love the eyes!</td>', 'Very nice portrait.  I love the eyes!', '2008-03-02 03:19:06.000000', NULL, 1),
(4531928, 651381, 18659, '<td valign="top">I am not sure if it is the lighting or not but the lip doesnt appear straight with top edge of photo.  On second look it might be that you have too wide a margin on the left and right, or maybe top left is too dark compared to top right.  Just seems unbalanced.</td>', 'I am not sure if it is the lighting or not but the lip doesnt appear straight with top edge of photo.  On second look it might be that you have too wide a margin on the left and right, or maybe top left is too dark compared to top right.  Just seems unbalanced.', '2008-03-02 03:24:35.000000', NULL, 1),
(4531961, 650150, 57775, '<td valign="top">Very cool &amp; creative idea.</td>', 'Very cool & creative idea.', '2008-03-02 03:39:46.000000', NULL, 1),
(4532197, 651733, 89423, '<td valign="top">I like how you can se the texture on the gecko</td>', 'I like how you can se the texture on the gecko', '2008-03-02 08:00:10.000000', NULL, 1),
(4532319, 651131, 13624, '<td valign="top">Almost looks like he''s got a large nose and is facing right! 7</td>', 'Almost looks like he''s got a large nose and is facing right! 7', '2008-03-02 09:46:16.000000', NULL, 1),
(4532368, 649659, 88590, '<td valign="top">Seems a little too soft for me - perhaps given the pastel colouring, this is the look you wanted to go for, but I feel it is oof.</td>', 'Seems a little too soft for me - perhaps given the pastel colouring, this is the look you wanted to go for, but I feel it is oof.', '2008-03-02 10:40:49.000000', NULL, 1),
(4532370, 652077, 88590, '<td valign="top">Seems a little too out of focus to me...</td>', 'Seems a little too out of focus to me...', '2008-03-02 10:42:29.000000', NULL, 1),
