(4533611, 651795, 89424, '<td valign="top">This photograph seems busy because of all of the textures and the different angles of the lines in the grass.</td>', 'This photograph seems busy because of all of the textures and the different angles of the lines in the grass.', '2008-03-02 22:18:16.000000', NULL, 1),
(4533616, 651971, 89424, '<td valign="top">This photograph is strong because it has a lot of texture. The vertical line of the nail emphasizes it because of it''s contrast agains the horizontal lines.</td>', 'This photograph is strong because it has a lot of texture. The vertical line of the nail emphasizes it because of it''s contrast agains the horizontal lines.', '2008-03-02 22:20:41.000000', NULL, 1),
(4533622, 651590, 89424, '<td valign="top">This photograph has a lot of depth and the hue matches very well but the photograph is a little noisy.</td>', 'This photograph has a lot of depth and the hue matches very well but the photograph is a little noisy.', '2008-03-02 22:21:51.000000', NULL, 1),
(4533623, 651737, 89424, '<td valign="top">The eye that is in focus makes this picture very strong and there is good use of space. The eye that isn''t in focus takes away from the picture.</td>', 'The eye that is in focus makes this picture very strong and there is good use of space. The eye that isn''t in focus takes away from the picture.', '2008-03-02 22:23:43.000000', NULL, 1),
(4533625, 651749, 89424, '<td valign="top">This picture is beautiful. There is a good use of space. Also it has a nice range of values. The yellow puts emphaisis on the middle of the flower. The only down sde is the border.</td>', 'This picture is beautiful. There is a good use of space. Also it has a nice range of values. The yellow puts emphaisis on the middle of the flower. The only down sde is the border.', '2008-03-02 22:25:06.000000', NULL, 1),
(4533627, 652068, 89424, '<td valign="top">There is a wide range of values on the pepper and the green stem leads the veiwers eye up the photograph.</td>', 'There is a wide range of values on the pepper and the green stem leads the veiwers eye up the photograph.', '2008-03-02 22:26:10.000000', NULL, 1),
(4533636, 649510, 89424, '<td valign="top">This photograph would be stronger if it was in focus. The subject is caputured from a viwer interesting angle, though there is alot of negative space.</td>', 'This photograph would be stronger if it was in focus. The subject is caputured from a viwer interesting angle, though there is alot of negative space.', '2008-03-02 22:28:08.000000', NULL, 1),
