(4536759, 651670, 90495, '<td valign="top">Is it just a bit underexposed? Good shot.</td>', 'Is it just a bit underexposed? Good shot.', '2008-03-03 23:50:50.000000', NULL, 1),
(4536766, 650848, 85310, '<td valign="top">I like the idea and the off-centre composition (with gradient to balance). The anal-retentive part of me would like to see even helical spacing on the orange peel, but then again, I don''t have to rig the strings and weights to accomplish that... ;-)<br/> <br/>The focus on the texture of the outer peel seems just a little soft. Perhaps you need to adjust your sharpening settings in your post-production phase?</td>', 'I like the idea and the off-centre composition (with gradient to balance). The anal-retentive part of me would like to see even helical spacing on the orange peel, but then again, I don''t have to rig the strings and weights to accomplish that... ;-) The focus on the texture of the outer peel seems just a little soft. Perhaps you need to adjust your sharpening settings in your post-production phase?', '2008-03-03 23:53:46.000000', NULL, 1),
(4536773, 652064, 85310, '<td valign="top">I like the restricted depth of field, but the leaf at left is unfortunately in the plane of sharp focus ... I think it would look better if it were blurred.</td>', 'I like the restricted depth of field, but the leaf at left is unfortunately in the plane of sharp focus ... I think it would look better if it were blurred.', '2008-03-03 23:55:41.000000', NULL, 1);
